fn finish(){assert_eq!(read(r("runs/result.json"))["status"],"complete");for(p,h)in read(r("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let jobs=read(r("jobs.json"));let(mut rows,mut counters,mut profiles,mut outputs)=(vec![],BTreeMap::new(),BTreeMap::new(),BTreeMap::new());let mut iterations=0u64;
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let text=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let results=text.lines().filter_map(|l|l.strip_prefix("RESULT ")).collect::<Vec<_>>();assert_eq!(results.len(),1);let v:Value=serde_json::from_str(results[0]).unwrap();assert_eq!(v["internally_verified"],true);assert_eq!(v["checked_Fq2_elements"],32);assert_eq!(v["iterations"],j["iterations"]);assert_eq!(v["pattern"],j["pattern"]);assert_eq!(v["conversion_outside_clock"],true);assert_eq!(v["profile_repeats"].as_u64().unwrap_or(1),j["repeat"].as_u64().unwrap());let units=j["iterations"].as_f64().unwrap()*j["repeat"].as_f64().unwrap()*8.*if j["pattern"]=="streams4"{4.}else{1.};assert!((v["ns_per_unit"].as_f64().unwrap()-v["elapsed_ns"].as_f64().unwrap()/units).abs()<1e-9);iterations+=j["iterations"].as_u64().unwrap()*j["repeat"].as_u64().unwrap()+6000;
  let key=format!("{}/{}",j["pattern"].as_str().unwrap(),j["iterations"]);if let Some(old)=outputs.insert(key,v["output_sha256"].clone()){assert_eq!(old,v["output_sha256"]);}rows.push(json!({"job":j,"result":v}));
  if j["panel"]=="stat"{let events=fs::read_to_string(j["data"].as_str().unwrap()).unwrap().lines().filter_map(event_line).collect::<BTreeMap<_,_>>();assert_eq!(events.len(),4);let per=events.iter().map(|(k,v)|(k.clone(),v["count"].as_f64().map(|n|n/units))).collect::<BTreeMap<_,_>>();counters.insert(name.to_string(),json!({"qualified":events.values().all(|v|v["qualified"]==true),"events":events,"per_Fq2_element":per}));}
  if j["panel"]=="cycles"{let events=fs::read_to_string(r(format!("runs/events-{name}/stdout.log"))).unwrap();for s in["cycles:u","16000000","CPU","TIME","PERIOD"]{assert!(events.contains(s));}assert!(!events.contains("freq: 1"));let meta=fs::read_to_string(r(format!("runs/metadata-{name}/stdout.log"))).unwrap();assert!(meta.lines().any(|l|l.contains("PERF_RECORD_MMAP")&&l.contains(j["binary"].as_str().unwrap())));assert!(meta.contains("PERF_RECORD_FORK"));assert_eq!(read(r(format!("runs/loss-{name}/stdout.log")))["zero_lost"],true);let(mut pids,mut syms,mut unknown,mut count,mut period)=(BTreeSet::new(),BTreeMap::<String,u64>::new(),0u64,0u64,0u64);for(pid,tid,cpu,weight,symbol)in fs::read_to_string(r(format!("runs/decode-{name}/stdout.log"))).unwrap().lines().filter_map(sample){assert_eq!(pid,tid);assert_eq!(cpu,2);assert_eq!(weight,16000000);pids.insert(pid);count+=1;period+=weight;if category(&symbol)=="unknown"{unknown+=weight;}*syms.entry(symbol).or_default()+=weight;}assert_eq!(pids.len(),1);assert!(count>0);let u=unknown as f64/period as f64;profiles.insert(name.to_string(),json!({"samples":count,"period":period,"unknown_period_share":u,"PIDs":pids,"symbols":syms,"attribution_qualified":count>=1000&&u<=0.05,"zero_lost":true,"CPU_verified":2,"absolute_period_coverage_not_validated":true,"repeated_arithmetic_intervals":2048,"single_final_scalar_oracle_outside_clock":true}));}
 }assert_eq!(iterations,898656408);let(mut cells,mut comparisons,mut calibration,mut failed)=(BTreeMap::new(),BTreeMap::new(),BTreeMap::new(),vec![]);
 for p in PS{let mut values=BTreeMap::new();for v in VS{let selected=rows.iter().filter(|row|row["job"]["panel"]=="latency"&&row["job"]["pattern"]==p&&row["job"]["variant"]==v).collect::<Vec<_>>();assert_eq!(selected.len(),31);let ordered=(0..31).map(|b|selected.iter().find(|row|row["job"]["block"]==b).unwrap()["result"]["ns_per_unit"].as_f64().unwrap()).collect::<Vec<_>>();cells.insert(format!("{p}/{v}"),json!({"median_ns":median(&ordered),"observations":ordered}));values.insert(v,ordered);}
  for control in["OFF","FROZEN","OLD_BASIS"]{let s=interval(&values["SQUARE"].iter().zip(&values[control]).map(|(a,b)|a/b).collect::<Vec<_>>());let required=p=="norm-affine"&&control!="OLD_BASIS";let passed=s["high"].as_f64().unwrap()<1.&&s["wins"].as_u64().unwrap()>=21;if required&&!passed{failed.push(format!("{p}/SQUARE/{control}/gain"));}comparisons.insert(format!("{p}/SQUARE/{control}"),json!({"statistics":s,"required":required,"gain_check":passed}));}
  let s=interval(&values["OFF"].iter().zip(&values["FROZEN"]).map(|(a,b)|a/b).collect::<Vec<_>>());let passed=s["low"].as_f64().unwrap()>=1./1.03&&s["high"].as_f64().unwrap()<=1.03;if !passed{failed.push(format!("{p}/OFF/FROZEN/calibration"));}calibration.insert(p,json!({"statistics":s,"passed":passed}));
 }save(r("rows.json"),&json!(rows));save(r("analysis.json"),&json!({"complete":true,"gate_passed":failed.is_empty(),"failed_checks":failed,"cells":cells,"comparisons":comparisons,"calibration":calibration,"counters":counters,"profiles":profiles,"new_native_tests":2,"new_native_field_outputs":132096,"integer_REDC_outputs":16528,"row_identity_checks":82640,"vector_iterations_including_primes":iterations,"production_changed":false,"conversion_outside_clock":true,"SDK_requests":0,"new_independent_exports":0,"proof_ledger":23971,"goal_achieved":false}));println!("Trace-one square gate{};{}failedchecks;0newSDK/Gnark",failed.is_empty(),failed.len());}
